import type { PortalAppSettingGroupCode } from './app-setting-groups';
import {
    REPORT_VIEW_COMMON_TAB_CODES,
    REPORT_VIEW_TAB_CODES,
} from './report-view.const';
import {
    REPORT_VIEW_LABEL_LIMITS,
    REPORT_VIEW_PLAN_COLUMN_CODES,
} from './report-view-labels.const';

/** Коды в обратных кавычках через запятую — для текста справки. */
const codeList = (codes: readonly string[]): string =>
    codes.map(code => `\`${code}\``).join(', ');

/**
 * ВНУТРЕННЯЯ документация категорий настроек для сотрудников April.
 *
 * Это не клиентская база знаний портала (та пишется для клиента и
 * упрощает): здесь механизм в терминах кода, к чему приведёт включение,
 * что подготовить на портале, риски и где смотреть результат. Поля и
 * стадии, нужные хукам категории, админка дописывает сама из каталога
 * хуков (`@lib/portal-lib/hooks`) — в тексте только то, чего там нет.
 *
 * Источники фактов: README модулей event-sales, `SALES_HOOKS_GUIDE.md`,
 * `LEAD_REQUEST_FLOW.md`, код фрейма «Звонки» (`front/apps/event-sales`,
 * `modules/app/consts/domain-config.ts`), описания ключей реестра. Если
 * клиентская статья расходится с кодом — здесь пишется поведение по коду.
 */
export const APP_SETTING_GROUP_DOCS: Partial<
    Record<PortalAppSettingGroupCode, string>
> = {
    portal_app: `**Механизм.** Приложение «April» ставится на портал как ЛОКАЛЬНОЕ приложение Битрикс24 (свои client_id/client_secret у каждого портала, строка \`garant_local:<домен>\` в «Секретах приложений»). Установка (\`apps/pbx\`, модуль marketplace) сохраняет токены и события жизненного цикла — и только. Виджеты и сущности CRM при установке НЕ ставятся.

**Параметры.**
- \`bitrix_auth_mode\` — чем бэкенд ходит в портал: \`webhook\` (ключ портала из настроек), \`app\` (токен установленного приложения с автоматическим обновлением через oauth.bitrix24.tech) или \`auto\` (по умолчанию — как было до 07.11.2026: токен приложения, если установка активна, иначе вебхук; так продолжают работать порталы, созданные установкой раньше, например april-dev). Читает \`PBXService.init\` с кэшем около минуты. Установка приложения сама закрепляет значение, если оно ещё не выбрано: новому порталу — \`app\`, действующему — \`webhook\`. Переключение меняет права ВСЕХ фоновых задач, хуков и фреймов портала: приложение видит не всё, что видит администратор (например, открытые линии).
- \`enabled_parts\` — части приложения по договору (\`sales\`, \`service\`). Пока только отображение в кабинете клиента; полная установка части по чек-листу — следующий шаг.
- \`app_widgets\` — какие виджеты должны стоять на портале. Применяется кнопкой «Обновить виджеты» в установках (diff: ставим недостающие из списка, снимаем НАШИ привязки, которых в списке нет; чужие не трогаем). Пустой список — ничего не ставим и не снимаем. У действующих порталов виджеты стоят старыми привязками (\`next.april-app.ru\`, \`front.april-app.ru\`) — список держим пустым до переезда на новые фронты, иначе в карточке появятся дубли.

**Риски.** Переключить \`bitrix_auth_mode\` на \`app\` у живого портала — то же, что сменить учётку всем кронам разом: проверять на тестовом портале. Виджеты из списка ставятся только после установки приложения на портал (нужен действующий токен).`,

    portal_bitrix_limits: `**Механизм.** Все наши приложения ходят в Битрикс портала через общий ограничитель запросов (\`libs/bitrix/core/rate-limit\`). Настройки читает \`PBXService.init\` (кэш около минуты) и передаёт ограничителю вместе с ключом портала; незаданные ключи — константы \`bitrix-rate-limiter.config\`, переменных окружения нет. Запросы двух классов: **интерактивные** (менеджер во фрейме) и **фоновые** (кроны, отчёты, разбор звонков).

**Параметры.**
- \`bitrix_rate_plan\` — скорость: обычный тариф 2 запроса/с с запасом 50, энтерпрайз 5/с и 250. Завышенный тариф — ошибки лимита Битрикса у всех; заниженный — медленные фронты и кроны, не успевающие за проход.
- \`bitrix_background_share_percent\` — доля запаса для фона (10–100, по умолчанию 60), остальное всегда за людьми. Больше доля — быстрее ночные проверки и отчёты, но днём менеджеры ждут дольше.
- \`bitrix_interactive_max_wait_sec\` — сколько ждёт запрос менеджера (15 с, максимум 120), потом идёт мимо очереди.
- \`bitrix_background_max_wait_sec\` — сколько ждёт фоновая задача (600 с, максимум 3600), потом откладывается; мимо очереди не идёт.

**Риски.** Выключать очередь (\`bitrix_rate_limit_enabled\`) только на время разбора: без неё менеджеры получают ошибки «превышен лимит», а кроны конкурируют с людьми.`,

    support_monitor: `**Механизм.** Крон приложения bot (\`apps/bot\`, \`SupportMonitorScheduler\`) раз в минуту обходит порталы с включённым \`support_monitor_enabled\` и смотрит линию не чаще, чем раз в \`support_monitor_poll_minutes\` минут. Один просмотр — две пачки запросов к порталу линии: список открытых диалогов (\`imopenlines.v2.Session.list\`, статусы «новый» и «взят оператором») и последние сообщения каждого диалога (\`im.v2.Chat.Message.tail\`). Правила — \`@lib/support\`.

**Когда оповещает.**
- Новый диалог — сразу.
- Клиент ждёт ответа \`support_monitor_remind_minutes\` минут — напоминание; \`support_monitor_escalate_minutes\` — срочный повтор. Ожидание считается от ПЕРВОГО сообщения клиента, на которое ещё не ответил сотрудник; ответ сотрудника гасит ожидание, следующее сообщение клиента запускает отсчёт заново. Системные сообщения и боты линии ответом не считаются. Статус «взят оператором» ответом тоже не считается: Битрикс ставит его при переводе диалога, даже когда клиенту никто не писал.
- Каждое событие — один раз; память о разосланном — в Redis на 7 дней. Ночью и в выходные оповещения тоже идут (решение владельца 26.10.2026).

**Куда.** Колокольчик — сотрудникам \`support_monitor_notify_user_ids\` на портале \`support_monitor_notify_domain\` (пусто — портал линии). Колокольчик одного диалога замещает предыдущий. Напоминание «клиент ждёт» — только взявшему диалог оператору, если он сопоставлен в \`support_monitor_operator_map\` («ID оператора линии: ID сотрудника колокольчика»); новый диалог и срочный повтор — всем. Telegram — в отдельный чат поддержки при \`support_monitor_telegram_enabled\`; бот и чат задаются в админке «Настройки приложения» → «Telegram-боты» (\`SUPPORT_TELEGRAM_BOT_TOKEN\`, \`SUPPORT_TELEGRAM_CHAT_ID\`), без них Telegram молча пропускается.

**Включение.** Задать \`support_monitor_line_id\` (на april-dev — 9), получателей и включить при \`support_monitor_dry_run\` = да: в журнал bot пишется, что ушло бы. Предпросмотр «что ушло бы сейчас» — ручка админки \`POST admin/support-monitor/preview\`. Потом выключить «только считать»: открытые диалоги объявятся заново, дальше — только новые события.

**Риски.** Ключ портала линии должен видеть все диалоги линии (на april-dev — вебхук администратора). Сбой Битрикса — тревога разработчику в Telegram не чаще раза в час, следующий просмотр пробует снова. На зеркале (\`APP_ROLE=standby\`) крон не работает.`,

    sales_visibility: `**Механизм.** Уровень видимости сотрудника (себя → группа → отдел → все отделы продаж) считается по снимку структуры компании (\`bx-department\`). Списки Bitrix ID здесь принудительно ПОДНИМАЮТ уровень и никогда не понижают: «группа» — себя и свою группу (без группы — отдел, вне отдела продаж — все), «отдел» — свой отдел продаж со всеми группами, «все» — вся структура продаж.

**Кто читает уровень.**
- KPI-отчёт: какие строки видны; вкладка «Финансы» и кнопка «Планы» — с уровня «отдел».
- Режим руководителя во фрейме «Звонки»: чьи дела видны.
- Серверная проверка руководителя (\`shared/head-access\`) на кнопках «Присоединить сюда» (\`join-to-main/run\`), «Присоединить к основной» (\`client-work/join\`) и «Объединить карточки компаний» (\`merge-duplicates/run\`). Руководитель — суперпользователь вендора, глава любого уровня по структуре или видимость шире своей из этих списков; сбой чтения структуры — отказ (fail closed).

**К чему приведёт.** Сотрудник из списка увидит чужие строки и дела и получит право присоединять сделки-дубли и сливать карточки компаний. Слияние карточек необратимо (вторая карточка удаляется) — давайте уровень только отвечающим за клиентов.

**Не путать с дефолтом для всех.** Уровень «что видят все рядовые сотрудники» задаётся в блоке «KPI-отчётность продаж» (\`visibility_employee_default\`) и действует только на KPI-отчёт: он не делает сотрудника руководителем, права на дубли и режим руководителя в «Звонках» от него не меняются. Списки здесь сильнее дефолта: человек из списка получает уровень списка, даже если дефолт ниже.`,

    kpi_sales_visibility: `**Механизм.** Роль пользователя в KPI-отчёте считает общий снимок структуры (\`bx-department\`, \`POST bx/department/structure\`). Фронт KPI-отчёта шлёт в запросе флаг \`applyEmployeeDefault\`, и только тогда бэк читает \`visibility_employee_default\` и расширяет периметр рядового сотрудника отдела продаж до выбранного уровня (\`applyEmployeeDefault\` в \`libs/bx-department\`): в ответе \`visibility\` и \`subordinateIds\` становятся шире, \`headOf\` остаётся \`null\`, источник — \`headOfSource = portal_default\`. Остальные потребители структуры (режим руководителя и кнопки дублей в «Звонках», AI-аналитика, библиотека конструктора) флаг не шлют и ничего не замечают.

**Правила.**
- Дефолт только поднимает: руководитель по структуре или человек из списков «Отдел продаж» с уровнем выше дефолта остаётся при своём.
- «Своя группа» у сотрудника отдела без групп означает свой отдел.
- Сотрудник вне отделов продаж (другой отдел, администратор) дефолт не получает — видит только себя, как раньше. Точечные списки «Отдел продаж» для таких людей работают по своим правилам (подъём до «все»).
- Суперпользователь вендора видит всё независимо от дефолта.

**К чему приведёт.** В отчёте, фильтре сотрудников и дайджесте рядовой увидит строки коллег выбранного уровня. Вкладка «Финансы», настройка планов, командное эфирное время, AI-витрина руководителя и публичные ссылки остаются только руководителям и суперпользователю: эти права считаются по \`headOf\`, а он у рядового не меняется. Баннер «Смотреть как…» подписывает такого сотрудника «менеджер (видит свою группу по настройке портала)».

**Применение.** Настройки портала кэшируются 5 минут; снимок структуры сбрасывать не нужно — роль считается при каждом запросе поверх снимка. Проверка: \`POST bx/department/structure\` с \`applyEmployeeDefault: true\` и \`userId\` сотрудника → \`visibility\` по настройке; тот же запрос без флага → \`own\`.`,

    kpi_report_view: `**Механизм.** Ключи только задают, что показывать: фронт KPI-отчёта (страница «Настройки отчёта» и сам отчёт) и список «Разборы звонков» читают их при открытии. Права доступа ими не меняются: вкладка или бейдж, скрытые здесь, не дают доступа к данным, которого у сотрудника нет, и открытые — не дают того, что ему не положено.

**Параметры.**
- \`report_view_tabs_hidden\` — коды вкладок отчёта через запятую (${codeList(REPORT_VIEW_TAB_CODES)}). Вкладки ${codeList(REPORT_VIEW_COMMON_TAB_CODES)} видят все сотрудники, поэтому хотя бы одна из них остаётся видимой: если скрыть все, «Все» всё равно покажется. Пусто — видны все вкладки, доступные по правам.
- \`report_view_charts_enabled\` — выключено: графики не показываются никому, остаются таблицы. На телефоне графики скрыты всегда.
- \`report_view_badges_main\` — бейджи-фильтры списка «Разборы звонков», которые видны сразу: идентификаторы общих бейджей и пунктов методики (с приставкой \`m:\`) через запятую, в порядке показа. Пусто — набор по умолчанию: основные из справочника и пункты методики с признаком основного. Остальные бейджи добавляются выбором из списка.
- \`report_view_labels\` — свои названия показателей, JSON-объект «ключ → название»: \`{"ev:presentation_plan":"Назначенная презентация","call:30":"Разговоры от 30 с","plan:calls_done":"План"}\`. Ключ — приставка и КОД показателя: \`ev:\` и код события отчёта (innerCode, включая \`result_communication_plan\` и \`result_communication_done\`), \`call:\` и бакет звонков (\`all\`, \`30\`, \`60\`, \`180\`, \`300\`, \`600\`), \`plan:\` и код планового показателя (${codeList(REPORT_VIEW_PLAN_COLUMN_CODES)}). Название — до ${REPORT_VIEW_LABEL_LIMITS.nameLength} знаков (пробелы по краям обрезаются), записей — до ${REPORT_VIEW_LABEL_LIMITS.entries}. Данные отчёта не меняются: название подставляется только при показе (таблицы, графики, чипы, Excel, публичная ссылка), поэтому сохранённые выборы колонок объединённого отчёта не теряются. Пусто или битый JSON — свои названия не заданы; запись с ключом не по шаблону при чтении отбрасывается, а страница настроек принимает только ключи из каталога показателей портала.
- \`report_view_plans_events\`, \`report_view_plans_merged\`, \`report_view_plans_callings\` — флаги колонок планов на вкладках «Все» и «События», «Объединённый отчёт», «Звонки». Включено — вплотную перед показателем стоит колонка его плана на выбранный период (если план настроен и показатель включён в настройках планов), а под фактом остаётся только процент выполнения. В Excel плановые колонки идут на основных листах, строки «— план» под сотрудниками тогда не выводятся, на листах рейтингов плановых колонок нет. Excel вкладки «Звонки» выгружает таблицу событий, поэтому флаг «Звонков» действует только в интерфейсе.
- \`report_view_plan_columns_hidden\` — коды плановых показателей через запятую, чью колонку плана не выводить (${codeList(REPORT_VIEW_PLAN_COLUMN_CODES)}). Пусто — выводятся все включённые в настройках планов. Финансов и эфирного времени в списке нет: их факта в таблицах нет.
- \`report_view_updated_by\`, \`report_view_updated_at\` — служебные: кто и когда последним сохранил настройки. Руками не правятся.

**Риски.** Коды бейджей вводятся текстом, без выбора из списка: опечатка означает, что бейджа в строке фильтров нет. Скрытая вкладка не видна никому на портале, включая руководителей, — перед скрытием «Финансов» или «AI аналитики» согласовать с владельцем отчёта. Свои названия в админке правятся руками только по ключам из справки: с опечаткой в ключе название просто не появится.

**Где смотреть.** Страница «Настройки отчёта» во фронте kpi-sales (меняет руководитель группы и выше); список «Разборы звонков» — бейджи сразу и остальные по выбору.`,

    ai_analytics_main: `**Механизм.** Витрина и рассылки строятся на разборах звонков (\`transcriptions\` и \`ais\` портала): разборы делает конвейер event-sales, его рубильник — поле \`enabled\` на вкладке «Настройки AI» карточки портала; ключи этой категории включают только ВИТРИНУ и рассылки kpi-report-sales поверх накопленных разборов. Ночью (03:45 по TZ портала) пересчитываются данные вкладки, в 05:30 — предрасчёт обзора за четыре недели. Время рассылок — по TZ из \`ai_analytics_calendar\`. Подробная теория и связи — путеводитель, раздел «Включение и рассылки».

**Что и когда уходит.**
- Алерты РОПам — сразу после разбора звонка, один раз на звонок, только по ошибке менеджера (решение владельца 11.11.2026): действующий флаг **conflict** (конфликт / грубость) или **compliance** (нарушение регламента) с дословной цитатой, неотработанное возражение (не ответил по существу или клиент ушёл из разговора), презентация без выявленных потребностей или без «свойство — связка — выгода». Срочный приоритет коучинга и возражение клиента сами по себе алерта не дают. Лимита в день и тихих часов нет: параметры \`alert_max_per_day\` и \`alert_quiet_*\` зарезервированы в реестре и пока не действуют. Без \`ai_analytics_rop_user_ids\` не уходят никому.
- Флаг \`door_closed\` («после отказа не оставил дверь открытой») в день звонка не шлётся — попадает в повестку понедельника. Флаги «обещание» и «негатив клиента» отменены (решение владельца 19.10.2026): у модели не спрашиваются и не показываются даже в старых данных.
- Утренний разбор менеджеру — 08:00 по рабочим дням (\`ai_analytics_digest_enabled\`); план дня в нём — \`ai_analytics_daily_plan_enabled\`.
- Сводный дайджест — 08:00 тем же кроном адресатам \`ai_analytics_digest_all_user_ids\`; от \`ai_analytics_digest_enabled\` НЕ зависит, но идёт только при \`ai_analytics_enabled\` — иначе слот пропускается с warn в логе (один раз на слот портала).
- Повестка недели РОПам — понедельник 08:30: три звонка недели по порядку сигналов **слабые презентации → слабая доработка → низкая оценка → риск с цитатой**.

**Доступ.** Витрина — руководителям (headOf) и суперпользователю; \`ai_analytics_self_view_enabled\` открывает менеджеру только его строки и на рассылки не влияет.

**Порядок включения.** \`ai_analytics_audit_enabled\` → аудит данных (раздел админки «AI-аналитика → Аудит данных»; от включения витрины не зависит) → уровни, цели, отсутствия (категория «сотрудники и цели») → \`ai_analytics_enabled\` → получатели и рассылки. \`ai_analytics_experiments_enabled\` — после стабилизации: система начинает вмешиваться (фокус недели, A/B скрипта), а не только советовать.

**После выкладки, меняющей сигналы.** Пульс и повестка живут в кэше (≤ 1 ч / ≤ 15 мин): без \`POST ai-analytics/cache/reset {domain, scope: "all"}\` (kpi-report-sales) руководители видят старый расчёт. Ручная проверка доставки — \`POST ai-analytics/push\` с \`recipients: [свой id]\`. Чек-лист — путеводитель, раздел «Запуск после выкладки».`,

    ai_analytics_people: `**Механизм.** Норма и цель менеджера считаются слоями: дефолт кода → портал → полоса стажа или уровень → параметры менеджера (сильнее всех). Все ключи — JSON, формат и ограничения — в описании каждой настройки; проверяйте JSON перед сохранением. Теория и связи — путеводитель, раздел «Сотрудники и цели».

**Три круга людей.** Периметр РАЗБОРА задаётся не здесь, а в настройках AI портала: пилот \`allowedUserIds\` либо весь отдел продаж (\`salesOnly\`); кого там нет — у того нет разборов, строки в витрине и переразбор истории его не касается. Периметр ВИТРИНЫ — руководители по структуре отделов и суперпользователь. Состав для НОРМ — строки периметра минус исключённые и ушедшие (параметры менеджера).

**Что на что влияет.**
- \`ai_analytics_levels\` — уровень назначает руководитель; пусто — подсказка по стажу (полосы \`tenure_bands\`, гистерезис на границе). Пока ключ пуст, читается временная запись \`ai-analytics-settings\` в ais.
- \`ai_analytics_targets\` — цели по уровням и личные переопределения; пусто — цель = медиана полосы стажа.
- \`ai_analytics_absences\` — отпуска, больничные, обучение вычитаются из экспозиции; без них отпуск выглядит провалом темпа. Длинный пропуск без записи модель считает отсутствием сама (\`absence_proxy_min_run\`).
- \`ai_analytics_manager_params\` — ставка, исключение из норм отдела, глушение алертов, наставник, свой календарь, статус ушедшего.
- \`ai_analytics_roster_confirmed_at\` — руководитель подтвердил состав и уровни (учитывается при \`roster_confirm_required\`).

**Пересчёт.** Смена пилота действует со следующего тика планировщика конвейера (до 30 минут) только для новых звонков; смена уровней, целей и отсутствий задним числом пересчитывает закрытые периоды лишь через \`POST admin/ai-analytics/backfill\` / \`recompute\`.

**Права сотрудников.** \`ai_analytics_style_opt_out\` — профиль стиля сотрудника не показывается никому (из норм коллег его строки пока не исключаются). Пул порталов (\`ai_analytics_pool_opt_in\`) — только обезличенные агрегаты, обязательна дата согласия \`ai_analytics_pool_consent_at\`; без неё при включённом пуле — ошибка конфигурации (шаг пула пропускается с причиной).`,

    ai_analytics_model: `**Механизм.** Ключи меняют то, КАК считается аналитика портала. Все — JSON, формат в описании настройки. Реестр параметров по группам, слои и пороги — путеводитель, раздел «Модель и данные»; прогноз — раздел «Прогноз отдела».

- \`ai_analytics_model_params\` — переопределения гиперпараметров реестра \`libs/sales-ai-analytics/src/params\` (слой портала); значение вне диапазона или чужого типа не применяется — действует дефолт кода, причина видна в «Как считаем». Пороги сигналов руководителю (решение владельца 19.10.2026): \`weak_section_score_max\` (5, [3; 7]) — средняя раздела не выше считается слабой; \`weak_section_gap\` (1, [0,5; 3]) — и ниже среднего по отделу на столько; \`low_score_call_max\` (4, [2; 6]) — звонок с оценкой не выше считается слабым; \`weak_followup_share_min\` (0,5, [0,2; 0,8]) — доля неотработанных возражений или шагов без даты для сигнала «слабая доработка»; \`n_min_none\` (8, от 5) — сколько наблюдений нужно, чтобы показать число; \`pulse_manager_min_n\` (8). Порядок правил «Внимания» и повестки: слабые презентации → слабая доработка → низкая оценка → … → риск последним и только с цитатой. Прогноз отдела: \`forecast_stage_enabled\` включается вручную после \`pass\` в \`GET admin/ai-analytics/forecast-backtest\`; пороги \`forecast_shadow_min_months\` (9) и \`forecast_backtest_min_months\` (6) можно снизить до 3; историю прогноза быстро даёт шаг \`forecast-log-replay\` (\`backfill\` на 24 месяца → \`recompute\` со steps). Цена модели — \`llm_price_per_1k\`.
- \`ai_analytics_definitions\` — горячий клиент, стадии «в решении», результативный звонок, минимальная длительность по типам, канон презентации.
- \`ai_analytics_scoring\` — потолки оценивания (до 20 правил) и стоп-фразы (до 100).
- \`ai_analytics_hypothesis\` — гипотеза «качество → объём»; без неё режим гипотезы в планах недоступен.
- \`ai_analytics_calendar\` — TZ, праздники и рабочие дни для окон «5 рабочих дней», «вчера» и времени рассылок; пусто или битый JSON — Europe/Moscow, пн–пт.
- \`ai_analytics_events\` — журнал событий портала (смена скрипта, цены, приход новичка): объясняет изломы трендов; автособытия разрыва ряда пишутся сюда сами.

**Сравнимость рядов.** Все разборы с начала накопления — одна серия от 25.06.2026 (\`AI_ANALYSIS_SERIES_START\`): минорные правки промпта (определения риск-флагов, новый тип «Приглашение на мероприятие», формулировки без смены шкалы) ряд не рвут, правка по существу — рвёт. Тип \`event_invite\` — отдельная колонка матрицы со своим n и оценкой, вне средней оценки, корзин, норм и советов; свои мероприятия портала — документ базы знаний kind \`call-analysis-event-invite\`. Переразбор истории текущей версией — \`POST admin/ai-analytics/reanalyze\` (сначала \`dryRun\`), после него \`backfill\` за месяцы периода и \`cache/reset\`.

**Риск.** Смена \`ai_analytics_definitions\` или \`ai_analytics_scoring\` рвёт сравнимость рядов: сохранение сдвигает \`comparableFrom\` вперёд, в журнал пишется автособытие разрыва ряда. Меняйте осознанно и одним пакетом.`,

    lead_sla: `**Механизм.** Крон \`lead-request-sla\` каждые 10 минут, под Redis-локом, только в рабочее время портала (календарь Битрикса). Порталы — с \`lead_intake_sla_enabled\`, перечитываются на каждом тике; env-настроек нет.

**Проход по лидам.** Выборка одним запросом: стадия «Назначена менеджеру» (\`lead_assigned\`) и \`DATE_MODIFY\` старше порога. Дальше по каждому лиду:
- сделка уже ушла из «Новой» — принятие задним числом (\`LeadRequestAcceptService\`, самоисцеление потерянного вебхука принятия), заявка остаётся у ответственного сделки;
- иначе история «Не принял за N мин», передача повторным ХО через хук «Лид → работа» (\`excludeResponsible\` — прежний, круг по отделу прежнего), уведомление руководителю отдела и заместителям;
- \`lead_intake_sla_max_transfers\` передач за сутки (3) — дальше передачи стоят, руководителям уведомление на каждой проверке, пока заявку не примут; счёт обнуляется через сутки после первой передачи.

**Проход по сделкам.** Сделки с непустым \`op_lead_assigned_at\` (таймер подтверждения, его ставит передача работы) старше порога передаются хуком «Передать работу»; сделки, затронутые лидовым проходом, пропускаются.

**Порог.** \`lead_intake_sla_minutes\` — рабочие минуты, не меньше 60; он же срок задачи обзвона при распределении по кругу. Повторной заявке — порог × \`lead_intake_sla_repeat_multiplier\` (3). \`lead_intake_sla_max_per_run\` (30) — защита от лавины после простоя.

**К чему приведёт включение.** Непринятые заявки начнут уходить другим сотрудникам; в KPI прежнему пишется «Холодный звонок Не состоялся», новому — «Запланирован»; руководители получают уведомления. Пока выключено, непринятая заявка остаётся у назначенного, хотя фрейм пишет о передаче.

**Перед включением.** Стадия лида «Назначена менеджеру» установлена (по ней выборка). Робот принятия на выход сделки из «Новой» (\`lead-request/accept/webhook?dealId=\`) желателен: без него принятие подхватит только этот крон, с задержкой до тика.`,

    lead_distribution: `**Механизм.** Ответственного выбирает хук «Лид → работа» (\`LeadToWorkAssigneeService\`), когда \`responsible\` не передан и \`isXo=Y\`. При конвертации (\`isXo=N\`) ответственный остаётся с лида.

1. **Отдел.** Подсказка \`department\` из робота или «Отдел строка» лида (\`department_string\`): сначала через \`lead_intake_department_aliases\`, затем по ID и названию — ОП, группа внутри ОП, любой подотдел ОП. Подотдел найден, но пуст — родительский ОП с предупреждением. **Не сматчилось вовсе — предупреждение и круг по ВСЕМ сотрудникам отделов продаж**; сырое значение подсказки пишется в лог \`[assignee]\`.
2. **Кандидаты.** Активные сотрудники отдела по снимку структуры (снимок обновляется раз в сутки, поэтому активность перед выбором перепроверяется на портале), минус руководители и заместители (остались одни руководители — назначается руководитель), минус отделы неработающих (\`lead_intake_inactive_department_ids\` и отделы со словами «не работающие», «уволен»), минус \`lead_intake_round_robin_excluded_user_ids\` (исключены все — круг среди них с предупреждением). Никого не осталось — заявка не назначается, предупреждение в результате операции.
3. **Выбор.** Round-robin с курсором в app-cache (\`rr:{отдел}\`, хранит userId — смена состава очередь не сбивает).

**Адресно.** Явный \`responsible\` (или «ОП Ответственный ХО» из БП) — круг не участвует; адресного из отдела неработающих хук заменяет кругом его отдела.

**Клиент из заявки.** \`lead_client_company_department_ids\` — отделы (с подотделами), где лид сотрудника, похожий на организацию, становится компанией, а не контактом (хук «Клиент из лида»).

**Расхождение с клиентской статьёй.** Клиентская база знаний (15.10.2026) пишет, что заявку без найденного отдела не назначают никому. По коду хука без соответствия заявка уходит в общий круг по всем ОП. Не назначается она только в страховке входа, когда у лида нет ни «ОП Ответственный ХО», ни «Отдел строка».`,

    lead_repeat: `**Механизм.** Режим хука «Лид → работа» при назначении входящей заявки (\`isXo=Y\`), не отдельный крон. Клиент ищется по признакам по порядку, решает первый найденный: номер заявки (\`lead_order_number\`) → ИНН (10/12 цифр с контрольной суммой, из поля или названия) → телефон (последние 10 цифр) → почта → корпоративный домен почты. Общедоступные почтовые сервисы по домену не сравниваются; \`lead_intake_repeat_excluded_email_domains\` дополняет этот список. Дальше — открытые сделки клиента в воронке ОП.

**Режимы \`lead_intake_repeat_join_mode\`.**
- \`off\` — повторная заявка заводит отдельную сделку.
- \`dry_run\` — сделка заводится как обычно, в ленту лида пишется «🔁 Повторная заявка — холостой ход» со ссылкой на сделку, к которой присоединили бы.
- \`on\` — присоединение.

**Что делает \`on\`.** Одна открытая сделка — заявка присоединяется к ней; несколько — к самой свежей по \`DATE_MODIFY\`, в ленты остальных пишется «возможный дубль», их менеджерам и руководителям — уведомление. Сделка переводится в «Новую», прежняя стадия запоминается в \`op_return_stage\` и возвращается после принятия. Есть открытая «Холодный обзвон…» — заявка привязывается к ней, вторая задача не создаётся. В историю сделки — «Повторное обращение (лид #…)»; поля заявки на сделке заменяются данными новой, телефоны и почты дополняются. Срок принятия — порог SLA × \`lead_intake_sla_repeat_multiplier\`. Клиент есть, открытых сделок нет — новая сделка на найденного клиента (ровно одна компания или один контакт).

**Не присоединяется.** Заявка, назначенная работающему сотруднику по имени; переведённая кнопкой «Преобразовать в работу»; к закрытой сделке. Ответственный найденной сделки уволен — заявка уходит по кругу, новому передаётся сделка клиента.

**Порядок включения.** \`dry_run\` на несколько дней, просмотр записей «холостой ход» в лидах, затем \`on\`.`,

    lead_duplicates: `**Механизм.** \`LeadToWorkDuplicateCheckService\` в хуке «Лид → работа»: при назначении входящей заявки (\`isXo=Y\`) ставит операцию хука «Проверка дублей» (\`duplicate-check\`) по лиду — только если в лиде ещё нет маркера \`op_lead_is_duplicate_check\`, иначе каждая передача заявки гоняла бы поиск заново. Конвертация (\`isXo=N\`) проверку не ставит.

**Что произойдёт.** Комментарий в таймлайн лида и сделки с кандидатами (до семи) и причинами совпадения, маркеры \`op_lead_is_duplicate_check\` и \`op_lead_is_duplicate\`. Ничего не объединяет и не закрывает.

**Глубина.** \`lead_intake_duplicate_check_deep\` — дополнительно ИНН в реквизитах, ИНН и название внутри названий компаний, лидов и сделок: точнее, но больше запросов к порталу.

**Перед включением.** Поля-маркеры на лиде. После установки \`op_inn\` лида сбросить кэш карты полей дублей (\`POST /api/duplicates/domain/{domain}/field-map/rescan\`), иначе ИНН из лида попадёт в поиск только через 24 часа.`,

    lead_rescue: `**Механизм.** Крон \`lead-intake-rescue\` каждые 30 минут, под Redis-локом, только в рабочее время портала. Ловит заявки, по которым вебхук назначения не дошёл (Битрикс вебхуки не повторяет) — их не видит и SLA, назначения не было. Найденное уходит тем же хуком «Лид → работа» (\`isXo=Y\`, \`stageMode=new\`, \`taskMode=close\`) с маршрутизацией из карточки; операции видны в мониторинге хука «Лид → работа».

**Где искать — решает портал.** Сопоставлена стадия «Очередь в ХО» (\`lead_xo_queue\`) — режим \`queue\`: вся стадия целиком, страницами по \`ID\`, без условий по датам; фильтр «только заявки» не применяется (очередь наполнил робот). Не сопоставлена — режим \`window\`: лиды, созданные за \`lead_intake_rescue_lookback_minutes\` (180), в любой открытой стадии, включая «Новый»; при \`lead_intake_rescue_requests_only\` — только распознанные заявки и входящие обращения.

**Признак «хук не проходил».** Пусты и \`op_lead_assigned_at\`, и \`to_base_sales\` — оба пишутся одной batch-группой хука; заполненность перепроверяется в коде (фильтр по пустому UF работает не на всех порталах).

**Гейт готовности (queue).** В лиде должно быть хотя бы одно из \`xo_responsible\` и \`department_string\` — иначе назначать некому, лид остаётся в очереди и считается в \`notReady\`.

**Лимит.** \`lead_intake_rescue_max_per_run\` (20) за проход, остальное — следующим тиком.

**Риски.** Режим \`window\` шире и опаснее: может забрать свежий лид, который сотрудник ведёт руками. На порталах с роботом входа сопоставьте «Очередь в ХО» — это основной режим.`,

    inn_legacy_fields: `**Механизм.** Вкладка «ИНН» сделки (и выбор ИНН договора в конструкторе) собирает варианты из наших полей «ИНН» и «ИНН варианты», реквизитов компании и контактов, заявок и названий. Своих старых полей портала («ИНН (new)», «ИНН организации») она не знает — их перечисляют здесь. Значения читаются при каждом открытии сделки, отдельного переноса нет.

**Параметры.** Три списка полей — для сделки, компании и лида. ИНН из полей сделки — вариант «из карточки сделки», из полей компании — «из карточки компании», из полей лида — «из заявки». В одном поле может быть несколько ИНН через запятую: каждый станет вариантом. Значения проверяются контрольной суммой; что её не прошло — не показывается.

**Сам ставится текущим.** Если текущий ИНН пуст и в сделке, и в компании, и его не дали реквизиты и заявки: берутся старые поля сделки; если там ровно один ИНН — он становится текущим (в сделке и компании), в ленте сделки — запись «из старых полей портала». Старые поля сделки пусты — так же по старым полям компании. Несколько разных ИНН — выбирает человек.

**Риски.** В старые поля ничего не пишется. Выбрано наше же поле «ИНН» — оно пропускается, чтобы не задвоить вариант.`,

    lead_to_deal: `**Механизм.** Что хук «Лид → работа» переносит из лида в сделку. Хук не выдумывает данные: что не заполнено в лиде, не переедет.

**Пишется всегда.** Связи: штатный \`LEAD_ID\` сделки (не перетирается, если там лид штатной конвертации), \`deal_from_lead_id\` и \`deal_joined_leads\` на основной И ХО-сделке, \`to_base_sales\` в лиде. ИНН: собирается из полей лида, компании, реквизитов и названий, проверяется контрольной суммой, пишется в \`op_inn_pool\` (все варианты) и \`op_inn\` (только если пусто). Данные заявки (телефоны, почты, регион, город, номер заявки, код партнёра, отдел, рекомендации, источник) — записью «Данные заявки» в таймлайн сделки со ссылкой на лид; запись идемпотентна. В поля сделки они не пишутся: собственных телефонов и почт у сделки в Битриксе нет.

**Настройки.**
- \`lead_work_origin_comment\` (вкл) — комментарий «Работа создана из заявки» в ленту НОВОЙ сделки; при reuse не пишется.
- \`lead_work_copy_activities\` (выкл) и \`lead_work_copy_activities_limit\` (50) — привязка последних дел лида к сделке (\`crm.activity.binding.add\`); в лиде дела остаются; потолок Битрикса — 100 привязок на дело. Fail-open: ошибка уходит в предупреждения операции.
- \`lead_work_link_client\` (выкл) — клиент из голого лида: контакт, а в отделах из \`lead_client_company_department_ids\` — компания; существующий клиент ищется по телефону и почте, при нескольких совпадениях заводится новый.`,

    calls_features: `**Как фрейм применяет флаги.** Фрейм «Звонки» при старте берёт \`GET /app-settings/event-sales\` (кэш-первым, обновление в фоне) вместе со списком \`storedKeys\`. Поверх доменных дефолтов из кода фрейма (\`DEFAULT_CONFIG\` и \`DOMAIN_OVERRIDES\` в \`modules/app/consts/domain-config.ts\`) кладутся ТОЛЬКО ключи, сохранённые на портале; дефолт реестра в админке ничего не решает. Явное сохранение перебивает домен в обе стороны, сброс возвращает доменный дефолт фрейма. Новое значение фрейм увидит при следующем открытии.

**Что делает флаг (по коду фрейма на 15.10.2026).**

| Настройка | Эффект во фрейме |
|---|---|
| \`with_no_plan\` | пропуск плана разрешён всегда (иначе «Без плана» — только когда у клиента больше одного дела) |
| \`with_no_call\` | кнопка «Недозвон» (отчёт без разговора); без флага кнопки нет |
| \`with_post_fail\` | при статусе «Отказ» (кроме контекста лида) обязательна дата следующего звонка, она пишется в \`post_fail_date\` сделки; её читает реанимация отказников при \`reject_revive_use_post_fail_date\` |
| \`with_color_required\` | при отчёте по клиенту с компанией отправка блокируется, пока прогноз компании не обновлён в этой сессии |
| \`with_check_presentation\` | после проведённой презентации с результатом — обязательный опросник («Хвост», «Итоги разговора», «Пять К»), ответы в поля опросника |
| \`with_tm\` | кнопка «В ТМЦ» на презентационных задачах со связанной ТМЦ-сделкой (режим ОП); **сейчас не действует**: ручка \`/pres/tmc-deals\` на бэке — заглушка, фрейм её не вызывает (\`BACKEND_SUPPORT_READY.tmcDeals = false\`) |
| \`with_department_mode_toggle\` | тумблер режима ОП/ТМЦ; начальный режим — сохранённый в браузере или по должности, без флага фрейм всегда в режиме ОП |
| \`with_presentation_animate\` | анимация кнопки «Проведена презентация» (по умолчанию вкл) |
| \`with_records\`, \`with_transcribation\`, \`with_ai\` | **сейчас не действуют**: фрейм гасит их общим гейтом \`ARE_CALLS_ENABLED = false\`; включение в админке ничего не изменит |
| \`with_no_reschedle\` | текущий фрейм флаг не читает (его использовало старое приложение) |
| \`questionnaires_disabled_event_types\` | выключает анкеты для выбранных типов событий (CSV кодов) |
| \`konstructor_slider_enabled\` | в чек-листах решения и продажи — кнопка слайдера карточки сделки с табом конструктора КП |
| \`action_prompts_enabled\` | подсказки «Записать ИНН?», «Проверить пересечения глубже?» и автопоиск пересечений при КАЖДОМ открытии; выключено — быстрее, поиск по требованию |
| \`relation_strips_enabled\` | полоски стадий других сделок клиента в карточках дел; цена — запрос сделок клиента на каждом открытии |`,

    calls_checklists: `**Механизм.** Чек-листы фрейма (\`features/CallChecklist\`) делают поля карточки клиента обязательными в момент планирования или отчёта: ответы пишутся в поля сделки, по ним строятся отчёты. Каталог вопросов — данные фронта; правка состава доезжает во фрейм в течение пяти минут без обновления приложения.

| Настройка | Когда | Что обязательно и куда пишется |
|---|---|---|
| \`checklist_refine_enabled\` | план «Доработка» | причина возражения — поле сделки «ОП Причина Отказа», с показом текущего значения |
| \`checklist_pay_enabled\` | план «Оплата» | дата последнего выставления счёта \`op_invoice_date\` (поле конструктора) |
| \`checklist_decision_enabled\` | план звонка по решению | дата КП и дата звонка по решению; проект договора, счёт, плановая дата покупки — по желанию |
| \`checklist_sale_enabled\` | отчёт «Продажа» | сумма сделки \`OPPORTUNITY\` и дата первой оплаты \`first_pay_date\` |
| \`checklist_report_enabled\` | отчёт по «Доработке», «Решению», «Оплате» | возражение и формулировка, исход решения с датой, обещанная дата оплаты — в поля клиента |
| \`task_checklist_enabled\` | создание задачи | чек-лист в задаче по типу события; отмеченное при закрытии — в историю карточки и комментарий задачи |
| \`refine_stage_on_plan_enabled\` | план «Доработка» | сделка переводится на «Доработку» даже с более поздней стадии — единственное исключение из правила «стадию нельзя понизить» |

**Перед включением.** Поля, в которые пишут чек-листы, должны быть установлены на сделке, иначе ответ некуда записать. \`task_checklist_enabled\` меняет вид задач у всех менеджеров портала — согласуйте с руководителем.`,

    calls_tasks: `**Механизм.** Все задачи обзвона фрейм ставит в группу \`task_group_id\` от имени постановщика \`boss_id\`; по этой группе «Звонки» находят дела менеджера, в режиме руководителя — дела сотрудников. Задачи вне группы фрейм не показывает (аудит сделок их учитывает).

**Ловушка нулевых значений.** \`0\` в \`task_group_id\` и \`boss_id\` означает «не задано»: действует значение по домену из кода фрейма. Дефолт 1 был ловушкой (инцидент 27.08): незаполненная настройка затирала рабочую группу, и дела «пропадали». Неверная группа — пустой список дел у всех менеджеров портала.

**Даты следующего события.**
- \`calculated_next_event_enabled\` (вкл) — «ОП Дата Следующего звонка», «ОП Тема Следующего звонка», «ОП Дата назначенной презентации» считаются по ВСЕМ открытым делам клиента, а не последним планом; работает со сборками фрейма, которые присылают список открытых дел.
- \`final_fields_reset_enabled\` (вкл) — продажа, отказ и «не ЦА» очищают даты и тему; выключать — только где карточку после финала ведут руками.`,

    call_analysis: `**Механизм.** Конвейер разбора звонков (call-report в \`apps/event-sales\`) переводит запись в текст через маршрутизатор распознавания. Звонок от порога «Длинный звонок — от» (маршрут в настройках AI портала, без него — порог приложения, 600 с) при \`call_transcription_chunks_enabled\` режется на куски по \`call_transcription_chunk_minutes\` минут прямо по кадрам MP3 — без перекодирования, соседние куски перекрываются на 10 с, хвост короче трети куска приклеивается к предыдущему. Куски распознаются по \`call_transcription_chunk_parallel\` одновременно (поверх общих лимитов распознавателей приложения); каждый кусок — по маршруту портала: бесплатные (VibeCode, свой Whisper) первыми, Яндекс последним, пока кто-то не справится. Склейка — по таймкодам: граница между кусками — середина нахлёста, повтор фразы на стыке убирается. Весь прогон — под замком звонка: второй запуск того же звонка получает «уже идёт» и пропускается. В маршруте нет ни одного бесплатного распознавателя (только Яндекс) — звонок не режется.

**Расход.** Распознаватель в строке расшифровки — тот, кто распознал больше всего секунд записи. Куски, ушедшие в Яндекс, видны в счётчике «отправок в Яндекс» страницы расхода с длительностью куска (ключ стража — \`<ключ звонка>:partNNofMM\`: замок, лимит и номер операции у каждого куска свои). Рубли страницы считаются по строкам расшифровки: звонок, записанный за VibeCode, в рубли Яндекса не попадает, даже если пара кусков ушла в Яндекс, — их видно только в счётчике отправок.

**Прогресс.** Готовый кусок сразу пишется в Redis (хеш \`stt-chunks:v1:<ключ звонка>\`, сутки): повторный запуск звонка распознаёт только оставшиеся куски и не платит Яндексу второй раз. После склейки ключ удаляется. Redis недоступен — звонок распознаётся без прогресса, в журнале предупреждение.

**Что даёт.** Длинные звонки (презентации до часа) распознаются бесплатно; Яндекс платится только за кусок, который не распознал никто другой, а не за весь звонок.

**Риски.**
- Запись не MP3 или битая — резать нельзя, звонок целиком идёт прежним путём.
- Кусок не распознал никто, включая Яндекс, — звонок не распознан (ошибка с номером куска), догон повторит только оставшиеся куски.
- Распознаватель без таймкодов — текст куска входит целиком одним сегментом на свою зону, повтор на стыке убирается грубо (по совпадению слов), звонок помечается «без таймкодов».
- Больше кусков одновременно — чаще «слишком много запросов» у бесплатного сервиса, и кусок уходит запасному.

**Где смотреть.** Журнал event-sales: «Звонок …: резка включена, N кусков по … с, распознали: Vibecode 11, Yandex 1; в расшифровку — …».`,

    reject_revive: `**Механизм.** Крон \`reject-revive\` раз в час, под Redis-локом, в рабочее время портала. Холодный звонок ставится внутренним вызовом холодного обзвона v2 (тот же буфер тишины, что у БП): задача «Холодный обзвон Реанимация отказа: …», срок — завтра 10:00 по времени портала, основная сделка в «Холодные» и ХО-сделка. \`force\` не передаётся — хук читает «ОП ХО с очищением?» (\`op_xo_is_force\`) из карточки.

**Кандидаты.** Только сделки воронки ОП на стадии «Отказ» (\`sales_fail\`), закрытые раньше \`reject_revive_interval_days\` (120) по \`CLOSEDATE\`; «Не состоялась», «Не ЦА», «Не Беспокоить» не возвращаются. При \`reject_revive_use_post_fail_date\` наступившая \`post_fail_date\` перебивает интервал, сделка с заполненной датой в интервальную ветку не попадает. README модуля устарел: там три стадии и вызов холодного обзвона v1.

**Двухфазная подстраховка.** До вызова на сделку ставится \`op_xo_revive_queued_at\`, после приёма буфером — \`op_xo_revive_sent_at\`. Фаза досылки идёт первой: queued старше \`reject_revive_resend_after_minutes\`, sent пуст. Обе фазы делят \`reject_revive_max_per_run\` (20). Окно двойной задачи одно — хук принят, а запись \`sent_at\` упала; принято сознательно: потерять клиента дороже.

**Назначение.** \`reject_revive_assign_mode\`: \`same\` — ответственному сделки на момент возврата; \`random\` — случайному активному сотруднику отдела продаж из слепка портала, пустой отдел — обратно \`same\` с предупреждением. Работает ли ответственный, НЕ проверяется: при \`same\` возвраты уволенных уйдут им.

**К чему приведёт включение.** По накопленным отказникам пойдут холодные звонки — до лимита за час, большой хвост растянется на дни. Клиента ведёт коллега — уступка («Холодный старт уступлен…»), если в карточке нет «ОП ХО с очищением?». Новый отказ чистит оба маркера и пишет свежую \`post_fail_date\` — цикл повторяется.

**Перед включением.** Поля сделки \`post_fail_date\`, \`op_xo_revive_queued_at\`, \`op_xo_revive_sent_at\` — без маркеров функция молчит (self-gate).`,

    lead_closing: `**Механизм.** После отчёта «Звонков» лиды рабочей основной сделки (её «Лид», «из лида», «присоединённые») закрываются по итогу сделки: в работе, «Успех» или «Отказ» — «Сконвертирован»; «Не ЦА» — «Некачественный лид» (в том числе уже сконвертированные — задним числом); «Не состоялась» — «Не состоялась», если у клиента нет другой работы; работа клиента идёт в другом отделе (сопровождение и т. п., с открытой задачей) — «Сконвертирован» с привязкой к компании клиента. Недозвон с перезвоном и кнопка «Недозвон» лид не закрывают: остаётся временный статус («Взята в работу», «Работа с компанией»).

**Задачи лида.** Перед закрытием открытые задачи лида не теряются: у привязанных к сделке снимается лид, задачи только на лиде переходят в сделку (работа живая) или закрываются (работа закончена), дела лида — в сделку. Битрикс закрывает открытые задачи лида вместе с ним, поэтому сначала задачи.

**Связи.** Лид ставится в поле «Лид» сделки — тогда сделка видна во вкладке «Связи» лида; у сделки «Лид» один, занят — ставится в компанию.

**Дубли.** Закрытые лиды (успех и брак) не показываются в поиске дублей.

**Статусы.** В «Стадиях лида» должны быть сопоставлены «Сконвертирован» (\`lead_converted\`), «Некачественный лид» (\`lead_junk\`) и «Не состоялась» (\`lead_apology\`); не сопоставлено — лиды не закрываются, в логе ошибка.`,

    report_takeover: `**Механизм.** Отчёт «Звонков» по клиенту, у которого открыта работа других сотрудников. Правило по умолчанию (25.08): чужое не трогаем — отчитавшемуся заводится своя основная сделка, в ленте обеих запись «договоритесь». Настройки группы меняют это правило.

**Боты обзвона.** \`xo_start_bot_user_ids\` — сотрудники, на которых ставят холодный обзвон для автодозвона (gsr: «Бот Манго»). Отчёт «Звонков» по клиенту с открытой основной сделкой бота забирает её отчитавшемуся менеджеру (стадия по плану, компания и контакты — за сделкой), а не заводит новую. Задачи бота по забранной сделке переходят менеджеру; прочая открытая работа ботов по клиенту закрывается так же, как при перехвате всей работы ниже: основные — в «Дубль» (\`sales_duplicate\`; не установлена — «Не состоялась»), ХО и презентации — «без результата», задачи, «Презентации» и «ЗПР» — закрываются, с записью в ленте. Иначе сделка, оставшаяся в стадии автодозвона, запускала бы звонки дальше. У менеджера уже есть своя открытая основная — она и остаётся, сделки ботов закрываются дублями. Отчитывается сам бот — перехвата нет. Работает без \`report_takeover_force\` и без подтверждения.

**Вся работа — отчитавшемуся.** \`report_takeover_force\`: то же, что у ботов, но у ЛЮБОГО сотрудника и у сделок без ответственного. Самая свежая открытая «ОП Основная» переходит к отчитавшемуся вместе с её открытыми задачами (запланированный звонок коллеги становится его звонком), стадия — по плану; остальные основные — в «Дубль». Чужие сделки ХО и презентаций, задачи, элементы «Презентаций» и «ЗПР» по клиенту закрываются — тем же способом, что при холодном обзвоне «с очищением». Своя работа отчитавшегося не трогается. Только воронки ОП (основная, ХО, презентации): ТМЦ, ОС и воронки, которых нет в нашей схеме, не трогаются.

**Подтверждение.** \`report_takeover_confirm\` (вкл): перед отправкой «Звонки» показывают, чья работа перейдёт или закроется, и менеджер выбирает «Забрать себе» или «Не забирать» (тогда — правило по умолчанию). Выключено — перехват без вопроса. Отчёт без явного «Забрать себе» при включённом подтверждении (старый фронт, робот) перехват не делает.

**Оповещение.** \`report_takeover_notify_previous\` (вкл): прежнему ответственному — уведомление в Битриксе, кто забрал клиента и что стало с его сделками и задачами. Запись в ленте сделок — всегда.

**Защита поздних стадий.** \`report_takeover_protect_from_stage\`: сделку коллеги на этой стадии «ОП Основная» и дальше перехват не забирает и не закрывает; она остаётся вместе со своими задачами, менеджер видит её в предупреждении. Пусто — защиты нет (нужно, когда висят сделки уволенных).

**Перед включением.** Согласовать с владельцем портала: перехват закрывает чужие сделки и задачи. Начать с подтверждением; «без вопроса» — когда команда привыкла.`,
    base_deal: `**Механизм.** Новую сделку «ОП Основная» создают три потока: отчёт «Звонков» (и досылка отчёта), хук «Лид → работа» и холодный обзвон v2. \`base_deal_title_assign\` включён (по умолчанию) — название по клиенту: отчёт — компания → основная сделка запуска → название компании из лида → лид → контакт; «Лид → работа» — компания → название компании из лида → лид; холодный обзвон — по \`xo_start_base_deal_title\`. Выключен — поле TITLE не передаётся ни одним потоком, сделку называет Битрикс («Сделка #N»), \`xo_start_base_deal_title\` при этом не действует.

**Что не меняется.** Существующие сделки не переименовываются ни в каком режиме. Сделки ХО, презентаций и ТМЦ называются по событию — настройка их не касается. Настройки не прочитались — поведение по умолчанию (название по клиенту).

**Когда выключать.** На портале своя автоматизация названий (номер Битрикса, реквизиты) и название от Апреля ей мешает.`,
    xo_start: `**Механизм.** Холодный обзвон v2 (БП, реанимация отказников, подстраховка) создаёт сделку ХО и, если открытой основной у клиента нет, новую основную в «Холодные». Обе новые сделки получают контакты клиента: компании, входной и сохранённой основной сделок, открытых лидов — те же, что адресный ХО переназначает новому ответственному. Существующая основная не меняется: ни название, ни контакты.

**Название.** \`xo_start_base_deal_title\`: \`default\` — название не задаётся, Битрикс ставит «Сделка #N»; \`client\` — название компании, у клиента без компании — название основной сделки запуска. Заглушки («Сделка #N», ИНН вместо названия) названием не считаются — тогда называет Битрикс. Сделка ХО всегда «Холодный обзвон …».

**Перед включением.** Проверить автоматизацию портала, которая сама переименовывает новые сделки: вместе с \`client\` она может задвоить название.`,

    xo_rescue: `**Механизм.** Крон \`xo-dispatch-rescue\` каждые 30 минут, под Redis-локом, в рабочее время портала. Сравнивает метки на компании и сделке: \`op_xo_revive_queued_at\` («взято в очередь», ставит БП перед вебхуком) и \`op_xo_revive_sent_at\` («хук отправлен», ставит Апрель после приёма). Queued новее sent дольше \`reject_revive_resend_after_minutes\` (120) — вызов не дошёл, крон досылает холодный обзвон v2 без очищения, не больше \`xo_rescue_max_per_run\` (20) карточек. Лиды не проверяет — их страхует страховка входа. Операций в мониторинге нет (буфер холодного обзвона), результат — в логах и карточках.

**Имена меток.** В реестре поля называются «ОП Реанимация: взято в очередь» и «ОП Реанимация: хук отправлен»; в БП портала они могут называться иначе («ОП Поставлен в очередь ХО», «ОП Отправлен в ХО»). Сверяйте по кодам.

**Границы.** \`xo_rescue_marker_since\` — момент включения: более ранние метки не досылаются никогда. \`xo_rescue_marker_max_age_hours\` (72) — более старая метка считается давним сбоем, в журнале «проверьте вручную».

**Второй способ — по дате звонка** (\`xo_rescue_orphan_*\`): \`xo_date\` прошла больше часа назад и попадает в окно \`xo_rescue_orphan_lookback_hours\` (96, можно в рабочих днях), sent нет, у компании нет сделки обзвона после этой даты. Ловит «БП упал до метки», но приблизительно: по умолчанию выключен, а \`xo_rescue_orphan_dry_run\` (вкл) пишет кандидатов только в лог.

**Перед включением.**
1. БП обзвона на компании и сделке: «Изменение документа» с полями ХО и меткой queued = \`{=System:Now}\` ДО вебхука. \`{=System:NowLocal}\` ложится со сдвигом пояса — каждый обзвон выглядит потерянным. БП, передающий всё в адресе вебхука без метки, крон не видит.
2. \`xo_rescue_marker_since\` = момент включения по времени портала.
3. \`xo_rescue_enabled\`; поиск по дате — выключен или вхолостую.

**К чему приведёт.** Досланные обзвоны создают работу как обычный холодный обзвон; клиент в работе у коллеги — уступка («Холодный старт уступлен»). Неверный \`marker_since\` или метки через \`NowLocal\` — массовая досылка уже отработанных обзвонов.`,

    konstructor_features: `**Механизм.** \`zakupki_enabled\` показывает в конструкторе КП блок «3 КП для торгов» (zakupki-offer): к нашему КП добавляются два КП от вымышленных поставщиков — пакет для закупочной процедуры клиента. Флаг читает фронт конструктора при старте; в легаси блок был включён только на april-garant.bitrix24.ru.

**Риски.** Документы от вымышленных поставщиков — только по явной договорённости с клиентом; включать точечно, на портал.`,

    tmc_approval_rescue: `**Механизм.** Крон \`tmc-approval-rescue\` (модуль event-report-tmc) каждые 30 минут, под Redis-локом, без привязки к рабочему времени: утверждение заявки — дневное действие, догнать упавший вызов нужно сразу. Порталы — с \`tmc_approval_rescue_enabled\`. На портале читается РПА «Заявка на презентацию» (код \`presentation\`): элементы в стадиях \`tmc_approval_rescue_stage_codes\` (по умолчанию \`rpa_pres_success\` — «Утверждено»), попавшие туда не раньше \`tmc_approval_rescue_lookback_hours\` (72) часов назад и не позже \`tmc_approval_rescue_grace_minutes\` (20) минут назад — роботу бизнес-процесса даётся время самому вызвать \`POST /api/event-sales/tmc/presentation-approved\`.

**Признак «уже обработано».** У ТМЦ-сделки заявки есть ссылка на pres-сделку (\`UF_CRM_TO_PRESENTATION_SALES\`), и у той ответственный — назначенный менеджер («ОП Кто назначен ответственным»), а дата презентации (\`next_pres_plan_date\`) совпадает с датой заявки до минуты. Так робот и крон не планируют одну презентацию дважды даже после очистки Redis; id операции у обоих один (ТМЦ-сделка + менеджер + минута даты). Повторная заявка по той же ТМЦ-сделке отличается датой или менеджером и признаком не перекрывается.

**Параметры согласования** крон берёт из самого элемента РПА: компания, контакт, ТМЦ-сделка, менеджер ОП, ТМЦ-менеджер («Кто назначил последнюю заявку»), руководитель (\`owner_op\`, иначе утвердивший заявку), дата, название, три комментария. Дальше — обычный отчёт «запланирована презентация» от имени менеджера (очередь EVENT_SALES_FLOW), как от робота: сделка и элемент смарта «Презентации», задача, KPI, ТМЦ-сделка в «Презентация назначена».

**Повторы.** Поставленная попытка помечается в AppCache на 30 дней: повтор не раньше чем через час, затем через шесть часов, после третьей — стоп и предупреждение в Telegram («провести вручную»). Заявка без менеджера, компании, ТМЦ-сделки или даты не проводится (предупреждение раз в сутки): робот с ней тоже не справился бы. Лимит \`tmc_approval_rescue_max_per_run\` (20) защищает от лавины после простоя.

**Перед включением.** Робот РПА перенацелен на новую ручку (иначе крон будет единственным, кто проводит согласования — это допустимо, но с паузой до получаса). На первые дни \`tmc_approval_rescue_dry_run\`: кандидаты только в лог (\`[холостой ход]\`), затем выключить. Где смотреть: лог приложения event-sales по \`tmc-approval-rescue\`, операции — статусы отчётов «Звонков».`,

    deal_audit: `**Механизм.** Крон\`event-sales-deal-audit\`: тик каждые 30 минут, под Redis-локом; портал аудируется по календарю \`deal_audit_frequency\` — \`weekly\` (ночь на понедельник) или \`monthly\` (ночь на 1-е), только ночью по часам портала: днём сотни запросов ушли бы в общий с менеджерами лимит Битрикса. Метка отработанного периода в Redis — частота меняется из админки без деплоя.

**Признаки** (открытые сделки воронки ОП; лимиты \`deal_audit_max_per_run\` и \`deal_audit_max_per_department\` за прогон):
- «Забыли закрыть» — стадии «Отправлены», «В решении», «В оплате», «Поставка» и \`deal_audit_forgot_close_days\` (21) без активности;
- «Без задач» — нет открытой задачи по сделке или её компании (отложенные не считаются, учитываются задачи любого сотрудника);
- «Просроченные задачи» — просрочка больше \`deal_audit_overdue_hours\` (24);
- «Давно нет работы» — \`deal_audit_idle_days\` (14) без активности в карточке;
- «Застряли в стадии» — \`deal_audit_stage_stuck_days\` (30).

**Поля.** \`op_audit_*\` на сделке пишет только крон (статус, признаки, дата, счётчики, расшифровка) — для фильтров и роботов. Без полей — self-gate: считает, пишет предупреждение «поля аудита не установлены», карточки не размечает; сводки при этом уходят.

**Чтобы пошли сводки** — три условия: \`deal_audit_enabled\`, \`deal_audit_dry_run\` выключено, хотя бы один получатель (\`deal_audit_digest_to_manager\`, \`deal_audit_digest_to_head\`, \`deal_audit_digest_department_user_ids\`, \`deal_audit_digest_user_ids\`). Канал доставки — галочки \`deal_audit_digest_channels\` (по умолчанию личное сообщение: руководителю — итог по сотрудникам и по сообщению на каждого; задача со сводкой — прошлая открытая задача-сводка закрывается; уведомление в колокольчике легко пропустить). Сводка уходит, только если забытые нашлись; новая заменяет прошлую; длина — \`deal_audit_digest_limit\`. \`deal_audit_digest_exclude_user_ids\` — чьих сделок нет ни в одной сводке (разметка карточек остаётся).

**Ручной запуск.** \`/deal-audit/run\` синхронный — на большой воронке ответ не доходит через прокси; используйте \`/run-now\` (фон, итог в Telegram) или точечные \`dealIds\`.`,

    deal_movement: `**Механизм.** Крон \`event-sales-deal-movement\` (модуль \`apps/event-sales/src/deal-movement\`): тик каждый час в :27, под Redis-замком; портал считается раз в сутки, когда у него 02:00–05:00 по своему поясу (\`deal_movement_enabled\`). Все открытые сделки «ОП Основная» читаются целиком (\`crm.deal.list\` курсором), история стадий — только у сделок, сдвинутых за окно (\`deal_movement_window_days\`), разборы звонков — из нашей БД за \`deal_movement_calls_lookback_days\` дней. Звонки, дела и задачи Битрикса (\`crm.activity.list\` по привязкам к сделке, одна страница свежих на сделку, пачками через ограничитель) читаются ТОЛЬКО у сделок, которым по разобранным звонкам и стадиям досталось бы «Без внимания», за тот же \`deal_movement_calls_lookback_days\`. «Контакт после договорённости» — разобранный звонок или любая активность по сделке позже даты договорённости.

**Статус** (считает код, первое сработавшее правило):
Подписи статусов для людей — в одном файле \`lib/deal-movement-status-titles.const.ts\` (код статуса → подпись); коды (\`rolled_back\`, \`abandoned\`, \`stuck\`, \`at_risk\`, \`moving\`) не меняются.
- «Вернулась назад» (\`rolled_back\`) — текущая стадия ниже самой высокой открытой, на которой сделка стояла в окне; переходы через закрытые стадии отбрасываются (переоткрытая сделка начинает заново), возврат на прежнюю стадию откатом не считается.
- Дольше срока в стадии. Срок — p90 дней в стадии по истории портала (закрытые эпизоды из уже прочитанной истории стадий, не меньше 20 эпизодов; «при обычных 34 днях для этой стадии»), иначе общий \`deal_movement_stuck_days\` (21; «при пороге 21 день»). Работы за окно нет — «Без внимания» (\`abandoned\`: «ни звонков, ни дел 40 дней; в стадии 50 дней при …»); работа есть (разобранный звонок, любой звонок из дел, в том числе недозвон, созданное или закрытое дело, задача, смена стадии), а стадия стоит — «Без продвижения» (\`stuck\`: «звонки 13.11 и 16.11 (недозвоны), стадия не меняется 50 дней при …»). Недозвон — звонок короче 20 с по началу и концу дела. «Последняя активность» сделки (\`LAST_ACTIVITY_TIME\`) работой НЕ считается: её сдвигают наши записи в ленту, роботы и бизнес-процессы (20.11.2026 ночью — 211 сделок от наших комментариев); она остаётся только для «контакта после договорённости». Дни в причинах — по поясу портала.
- «Под риском» — договорённость просрочена; две оценки продвижения 1 подряд; согласие клиента (4–5), а стадия стоит \`deal_movement_agreed_still_days\` (12) дней.
- «Движется» — всё остальное.

**Версия расчёта.** Метка счёта хранит \`DEAL_MOVEMENT_CALC_VERSION\`; другая версия (20.11.2026 — 2.0.0) — базовая линия заново: прежний «stuck» значил другое, ложных смен статуса нет.

**Хранение.** Состояние по сделкам — Redis-хеш \`event-sales:deal-movement:state:{домен}\` (7 суток, продлевается каждым счётом); счёт старше 3 суток — базовая линия заново, чтобы после простоя не вывалить накопленные смены разом. Дневной снимок с итогом и сменами статуса — запись \`ai-analytics-deal-movement\` в ais. Сделка, увиденная впервые, получает базовую линию.

**Что делает по умолчанию.** Только считает: в сделки ничего не пишется, сотрудникам ничего не уходит, итог ночи — в Telegram команды.

**Сводка руководителям** (\`deal_movement_digest_enabled\`, выключено). Только после ночного счёта по расписанию (не после ручного и не после «Посчитать»), один раз за день портала (отметка в Redis). Получатели и каналы — как у сводки аудита сделок (\`deal_audit_digest_*\`: менеджеру, РОПу, общий список, по своему отделу, исключённые, уведомление / сообщение / задача); выбор — \`routeRecipients\` из \`@lib/rop-reports\` (сделка, владелец — ответственный, «шире побеждает», сироты не рассылаются); неработающим не уходит. Режим \`deal_movement_digest_mode\`: «только новые» — если в наборе получателя есть новая проблема этой ночи: переход из «Движется» в любой проблемный статус или ухудшение (тяжесть: движется < без продвижения < под риском < без внимания < вернулась назад; улучшение — не новая проблема); «каждое утро» — если в наборе есть хоть одна сделка не «движется»; «раз в неделю» / «раз в две недели» — в день \`deal_movement_digest_weekday\` (1–7, понедельник) по поясу портала и не чаще 7 / 14 дней (отметка \`event-sales:deal-movement:digest-last:{домен}\`); внутри — счёт по статусам, «с прошлой сводки стали …» (по моменту смены статуса), крупнейшие проблемные, «Без внимания» отдельным блоком и «Давно без продвижения» — напоминания по ступеням: дни в стадии больше срока в 2, 3, 4… раза, каждая ступень один раз (ступень — \`remindedStep\` в состоянии сделки, сброс сменой стадии); в ежедневную сводку и в ленту напоминания не идут. Внутри: счёт по статусам набора, «Новые за ночь» (до 15, важные первыми, было → стало, причины), «Под риском» — первые \`deal_movement_digest_top\` (15) по сумме (при равной — дольше в стадии), без повторов из «Новых»; имена ответственных — из структуры отделов. Находки аудита сделок: аудит в конце каждого прогона (планового и ручного) пишет их в Redis-хеш \`event-sales:deal-audit:findings:{домен}\` (35 суток; «норма» удаляется); сводка берёт свежие (не старше 8 суток, при аудите «раз в месяц» — 32) и показывает пометкой «ещё и по аудиту: …» (до двух признаков) под причинами сделки и числом «из них забыты по аудиту» в шапке, Telegram и снимке. Отдельного раздела нет — список забытых приходит сводкой аудита; статус сделки находки не меняют.

**Запись в ленту** (\`deal_movement_write_notes\`, выключено). Сделке, у которой статус разошёлся с последним «сказанным» (\`notifiedStatus\`), пишется одна запись: статус словами, было → стало, причины, дней в стадии, у проблемных статусов — блок «Что сделать»; «Без внимания» в ленту не пишется (сделку никто не открывает) — смена на него считается «сказанной» молча, в конце — что статус посчитала программа. Вид — \`deal_movement_note_kind\`, по умолчанию служебная запись журнала (\`crm.timeline.logmessage.add\`): по проверке 18.11.2026 на сделке april-garant 34862 она НЕ сдвигает «последнюю активность» сделки, тогда как комментарий (\`crm.timeline.comment.add\`, заголовок жирным через BB-код) — сдвигает. Уже сохранённые на порталах значения не менялись. Пишет ТОЛЬКО ночной счёт по расписанию: ручной счёт из админки оставляет расхождения до ночи (в итоге — сколько отложено), днём записей и вызовов модели нет. По одной, не пачкой, пауза ~1 с, без автоповтора; не чаще раза в 3 суток на сделку; за ночь не больше \`deal_movement_max_notes\` (100) на портал (счётчик дня в Redis); сначала тревожные статусы и крупные суммы. Удалась — \`notifiedStatus\` и \`notifiedAt\` (момент самой записи) сохраняются сразу (одно поле хеша); не удалась — расхождение остаётся до следующей ночи, в итоге — «не удалось». Базовая линия ничего не пишет; «Посчитать» показывает, сколько записали бы.

**«Что сделать».** Модель портала (\`deepAnalysisModel\`) получает статус и причины словами, дни в стадии, последнюю договорённость и резюме последнего разобранного звонка; отвечает строгой схемой — 3–5 строк. Строка выбрасывается, если в ней больше 25 слов, латиница, число не из входа, число словами, стоп-слово или утверждение о причине; осталось меньше двух — запись без блока. Нет ни разобранного звонка, ни договорённости — модель не зовётся, лимит не тратится: причины статуса в записи уже есть. Не больше \`deal_movement_max_texts\` (50) вызовов за ночь на портал. Статус модель не ставит.

**Своя запись — не активность.** Если «последняя активность» сделки попала в окно [запись − 2 мин; запись + 15 мин], берётся прошлое значение из состояния: наша запись не выдаётся за контакт после договорённости (работой по сделке «последняя активность» не считается вовсе).

**Ручной запуск.** Админка: \`POST admin/ai-analytics/deal-movement\` с \`dryRun: true\` — «Посчитать» (ничего не сохраняется, итог в состоянии прогона), \`dryRun: false\` — внеочередной счёт (сохраняет состояние и снимок, в ленты не пишет — записи ждут ночи); состояние — \`GET admin/ai-analytics/deal-movement-status\`. Замок портала общий с кроном.

**Проверка записи.** \`POST admin/ai-analytics/deal-movement-probe\` (\`domain\`, \`dealId\` — открытая сделка «ОП Основная») пишет в сделку служебную запись журнала и комментарий «Проверка записи в ленту — служебная, можно удалить» и смотрит, сдвигают ли они «последнюю активность»; итог — \`GET admin/ai-analytics/deal-movement-probe\`. Пишет в живой портал — только руками.

**Потолок.** \`deal_movement_max_deals\` (10 000): открытых больше — оцениваются самые новые по номеру, остальные сохраняют прошлый статус, в итоге — предупреждение.`,

    duplicate_report: `**Механизм.** Крон \`event-sales-duplicate-report\`, тик каждый час. Отчёт — раз в неделю: день \`duplicate_report_weekday\` (1–7) и час \`duplicate_report_hour\` по TZ портала. Не ушёл в свой час (портал или Битрикс недоступны) — уйдёт позже на той же неделе, не раньше часа отправки; после пяти неудач неделя пропускается (первый и последний сбой — в Telegram).

**Что строит.** Клиенты (компания, без неё контакт) с двумя и более открытыми сделками воронки ОП. Разбор: основная (работающий ответственный → дальше по воронке → сумма → нормальное название → задачи), самая свежая (к ней присоединится следующая заявка), «решить руководителю» (двое работающих ведут сами или разные \`op_inn\`), «как появилась» (лид-источник \`deal_from_lead_id\`, иначе \`LEAD_ID\`). Сделки НЕ трогает — только читает CRM и ставит задачи.

**Что уходит.** Задача «Дубли сделок: отчёт за неделю …» с Excel на Диске (папка «Отчёты по дублям сделок»), срок — конец \`duplicate_report_deadline_days\`-го рабочего дня по календарю портала; прошлая задача закрывается сама. Задача намеренно не привязана к CRM — иначе сбивала бы менеджеров и счётчик открытых задач аудита сделок.

**Кому.** \`duplicate_report_to_head\` — руководителю отдела по структуре (с подъёмом по PARENT); \`duplicate_report_department_user_ids\` — отдел и подотделы получателя; \`duplicate_report_user_ids\` — все клиенты портала; человек в нескольких списках получает одну задачу; неработающим не ставится. \`duplicate_report_exclude_user_ids\` — чьих сделок в отчёте нет вовсе.

**Чтобы задачи пошли.** \`duplicate_report_enabled\`, \`duplicate_report_count_only\` выключено, хотя бы один получатель; вебхук портала со scope \`disk\` и \`task\`. В режиме «только считать» итог уходит только в Telegram.

**Зависимость.** Инструкция в задаче ведёт в блок «Открытые сделки по клиенту» во фрейме — без него руководитель не выполнит задачу.`,

    period_digest: `**Состояние.** Настройки заведены заранее (этап 7.4): расчёт карточек уже есть в \`@lib/sales-ai-analytics\` (model/period-digest), крон и задачи в event-sales подключаются следующими этапами — до их выкладки настройки ни на что не влияют.

**Механизм.** Крон event-sales на каркасе \`@lib/rop-reports\`: тик раз в час, под Redis-замком тика и портала. Виды — \`period_digest_kinds\`: неделя (прошлая ISO-неделя, пн–вс) уходит в день \`period_digest_weekday\` с часа \`period_digest_hour\` по поясу портала, нерабочий по календарю портала день пропускается; месяц — в первый рабочий день нового месяца с того же часа. Не ушло (портал или Битрикс недоступны) — догон до конца недели или месяца, после пяти неудач период закрывается без отчёта (первый и последний сбой — в Telegram).

**Что считает.** Карточку «менеджер × период» по разобранным звонкам из нашей БД — Битрикс для счёта не нужен: объём, шаг с датой, «дней без записанных звонков», средняя оценка и разделы, худший и лучший раздел, доработка, методика. Сравнение — с прошлым периодом того же вида и (у месяца, если есть данные) с тем же месяцем год назад; положение в отделе — только словами, без мест. Рекомендации дают восемь модулей поверх правил «Внимания» (сначала презентации): не больше трёх активных у месяца и двух своих у недели, у каждой — метрика, база и цель. Рекомендация живёт три оценки: цель две оценки подряд — «закрепить», только на третьей — «закрепить, держать», иначе — «обсудить с РОПом»; ни одной оценки с данными — «снята: данных не было». Неделя показывает шаги к целям месяца. Карточки хранятся снимками в ais.

**Пороги.** \`period_digest_min_calls\` (5): разобрано меньше — карточка с пометкой «мало данных», числа есть, новых рекомендаций нет, прошлые оцениваются. \`period_digest_shift_score\` (0,5 балла) и \`period_digest_shift_share\` (10 процентных пунктов) — заметное изменение: «стало лучше / хуже», «выше / ниже середины отдела», цель рекомендации — на два таких шага лучше. Минимум наблюдений под метрикой рекомендации — 3 за неделю и 5 за месяц (в коде).

**Кому.** \`period_digest_to_head\` — руководителю отдела по структуре (с подъёмом по PARENT; менеджеры, которых не к кому отнести, — руководителям верхних отделов продаж); \`period_digest_department_user_ids\` — отдел и подотделы получателя; \`period_digest_user_ids\` — все менеджеры портала; роли одного человека сводятся в одну задачу; неработающим не ставится. \`period_digest_exclude_user_ids\` — по кому итоги не считаются вовсе. «Сводки сотруднику» нет: в Excel оценки и рекомендации по каждому коллеге, витрина — только руководителям (решение 07.09).

**Что уходит.** Задача с итогами (BB-код) и Excel на личном Диске владельца вебхука, папка «Отчёты РОПу» (не папка группы «Продажи» — её видят менеджеры); срок — \`period_digest_deadline_days_week\` (3) или \`period_digest_deadline_days_month\` (5) рабочих дней по календарю портала; прошлая задача того же вида закрывается сама.

**Чтобы задачи пошли.** \`period_digest_enabled\`, хотя бы один вид в \`period_digest_kinds\`, \`period_digest_count_only\` выключено, хотя бы один получатель; вебхук портала со scope \`disk\` и \`task\`. В режиме «только считать» карточки считаются и сохраняются, итог — только в Telegram.`,

    skap_import: `**Механизм.** Крон-конвейер event-service (\`SkapImportScheduler\`): тик каждые 30 минут под Redis-локом, портал прогоняется не чаще \`scan_interval_minutes\` (60 на обкатке, 10080 — раз в неделю в работе). Прогон — очередь \`SKAP_IMPORT\` (\`jobId={domain}:run\`), тайм-бюджет \`max_run_minutes\` (180), не больше \`max_files_per_run\` файлов. Параллельность доменов — env \`SKAP_IMPORT_CONCURRENCY\` (2).

**Что делает.** Забирает выгрузки (zip или csv) из папки «СКАП. Загрузка» на Диске группы отдела сервиса, сверяет формат по именам колонок, матчит компанию по \`UF_CRM_USER_CARDNUM\`, сделку сервиса — по датам договора, контакт — по email-логину, пишет элементы смарта «СКАП» (логин клиента × месяц, \`xmlId=skap_{card}_{login}_{YYYY-MM}\`) и сессии/подписки в БД; сессии месяца — комментарием в таймлайн элемента. Месяцы старше \`max_history_years\` пропускаются.

**Идемпотентность.** Три уровня: unique \`dedup_key\` в БД, \`jobId\` очереди, \`xmlId\` элемента. Перезалитый файл (изменились время или размер) переобрабатывается обновлением, а не дублем.

**Перед включением.** Таблицы \`skap_*\` накатаны; группа сервиса установлена (группы звонков, «ОС Звонки»); смарт «СКАП» установлен из галереи смартов; затем \`enabled\`. \`group_id = 0\` — группа сервиса из PortalDB; \`folder_id\` и \`folder_url\` — кэш, их заполняет первый прогон.

**Уведомления и сбои.** \`notify_user_ids\` — Bitrix ID получателей сводки на портале (пусто — только Telegram-дайджест в админ-чат), \`digest_level\` — все прогоны / только ошибки / выкл. Пропала обязательная колонка — файл помечается \`error_format\` и сразу уходит Telegram-алерт. Мониторинг прогонов, файлов и элементов, повтор и переобработка — раздел админки СКАП.`,
};
